package expo.modules.placementguard
import org.json.*
import java.net.*
import java.io.*
data class Classification(val placementRelated:Boolean,val confidence:Double,val reason:String)
class NimClassifier{
 fun classify(apiKey:String,model:String,sender:String,messages:List<String>):Classification{
  require(apiKey.isNotBlank()) { "Enter your NVIDIA API key in settings" }
  val system="""You are a strict binary classifier for a college placement coordinator's personal WhatsApp. Decide whether the recent conversation is about campus placements/recruitment. Placement includes companies visiting campus, eligibility, registration, applications, OA/assessments, coding tests, PPTs, interviews, GD, shortlists, results, offer letters, CTC/package, internship/PPO/FTE, joining/onboarding, forms/deadlines, TPO/placement-cell/PR coordination, venue/reporting time, recruitment links, attendance, and contextual follow-up questions. Not placement includes personal chat, food, travel, friendship, ordinary academics/classes, casual greetings, clubs/events unrelated to recruitment, general tech questions, spam, or ambiguous messages with insufficient placement context. Messages may be English, Hindi, or Hinglish. Be conservative. Return ONLY JSON: {\"placement_related\":true|false,\"confidence\":0.0-1.0,\"reason\":\"short reason\"}."""
  val body=JSONObject().put("model",model).put("temperature",0.2).put("top_p",0.7).put("max_tokens",100).put("stream",false).put("messages",JSONArray().put(JSONObject().put("role","system").put("content",system)).put(JSONObject().put("role","user").put("content","Sender: $sender\nRecent context:\n"+messages.takeLast(6).joinToString("\n"))))
  val c=(URL(AppConfig.NIM_ENDPOINT).openConnection() as HttpURLConnection).apply{requestMethod="POST";connectTimeout=12000;readTimeout=25000;doOutput=true;setRequestProperty("Authorization","Bearer ${apiKey}");setRequestProperty("Content-Type","application/json")}
  c.outputStream.use{it.write(body.toString().toByteArray())};val code=c.responseCode;val stream=if(code in 200..299)c.inputStream else c.errorStream;val raw=stream.bufferedReader().use{it.readText()};if(code !in 200..299) throw IOException("NIM HTTP $code")
  val content=JSONObject(raw).getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content").trim().removePrefix("```json").removePrefix("```").removeSuffix("```").trim();val o=JSONObject(content);return Classification(o.optBoolean("placement_related",false),o.optDouble("confidence",0.0),o.optString("reason",""))
 }
}

package expo.modules.placementguard
import android.content.Context
class SettingsStore(context: Context){
 private val p=context.getSharedPreferences("placement_guard",Context.MODE_PRIVATE)
 var apiKey:String get()=p.getString("apiKey","")!!; set(v)=p.edit().putString("apiKey",v.trim()).apply()
 var enabled:Boolean get()=p.getBoolean("enabled",true); set(v)=p.edit().putBoolean("enabled",v).apply()
 var dryRun:Boolean get()=p.getBoolean("dryRun",true); set(v)=p.edit().putBoolean("dryRun",v).apply()
 var ignoreGroups:Boolean get()=p.getBoolean("ignoreGroups",true); set(v)=p.edit().putBoolean("ignoreGroups",v).apply()
 var threshold:Float get()=p.getFloat("threshold",.85f); set(v)=p.edit().putFloat("threshold",v).apply()
 var cooldownHours:Int get()=p.getInt("cooldown",24); set(v)=p.edit().putInt("cooldown",v).apply()
 var model:String get()=p.getString("model",AppConfig.MODEL)!!; set(v)=p.edit().putString("model",v).apply()
 var replyText:String get()=p.getString("reply",AppConfig.DEFAULT_REPLY)!!; set(v)=p.edit().putString("reply",v).apply()
 var exclusionsRaw:String get()=p.getString("exclusions","")!!; set(v)=p.edit().putString("exclusions",v).apply()
 fun excluded(sender:String)=exclusionsRaw.lines().map{it.trim().lowercase()}.filter{it.isNotEmpty()}.any{ sender.lowercase().contains(it) }
}

package expo.modules.placementguard
import android.content.Context
class CooldownStore(c:Context){private val p=c.getSharedPreferences("pg_cooldowns",Context.MODE_PRIVATE);fun canReply(s:String,h:Int):Boolean{val k=s.lowercase();val t=p.getLong(k,0);return t==0L||System.currentTimeMillis()-t>=h*3600000L};fun mark(s:String){p.edit().putLong(s.lowercase(),System.currentTimeMillis()).apply()}}

package expo.modules.placementguard
import android.app.*
import android.content.*
import android.os.*
import android.service.notification.*
import android.app.RemoteInput
import java.util.concurrent.Executors
class WhatsAppNotificationListener:NotificationListenerService(){
 private val pool=Executors.newSingleThreadExecutor();private val recent=mutableMapOf<String,MutableList<String>>();private val seen=mutableSetOf<String>()
 override fun onNotificationPosted(sbn:StatusBarNotification){
  if(sbn.packageName!=AppConfig.WHATSAPP_PACKAGE)return
  val n=sbn.notification;if(n.flags and Notification.FLAG_GROUP_SUMMARY != 0)return;val e=n.extras;val title=e.getCharSequence(Notification.EXTRA_TITLE)?.toString()?.trim().orEmpty();val text=e.getCharSequence(Notification.EXTRA_TEXT)?.toString()?.trim().orEmpty();if(title.isBlank()||text.isBlank())return
  val sig="$title|$text|${sbn.postTime/3000}";synchronized(seen){if(!seen.add(sig))return;if(seen.size>200)seen.clear()}
  val st=SettingsStore(this);if(!st.enabled||st.excluded(title))return
  val isGroup=e.getBoolean(Notification.EXTRA_IS_GROUP_CONVERSATION,false)||e.getCharSequence(Notification.EXTRA_CONVERSATION_TITLE)!=null;if(st.ignoreGroups&&isGroup){ActivityLog.add(this,"ignored group: $title");return}
  val history=synchronized(recent){val list=recent.getOrPut(title){mutableListOf()};list.add(text);while(list.size>6)list.removeAt(0);list.toList()}
  pool.execute{try{val r=NimClassifier().classify(st.apiKey,st.model,title,history);ActivityLog.add(this,"$title -> placement=${r.placementRelated} ${"%.2f".format(r.confidence)}");if(!r.placementRelated||r.confidence<st.threshold)return@execute;val cd=CooldownStore(this);if(!cd.canReply(title,st.cooldownHours)){ActivityLog.add(this,"cooldown: $title");return@execute};if(!SettingsStore(this).enabled)return@execute;if(st.dryRun){ActivityLog.add(this,"TEST would reply to $title");return@execute};if(sendReply(n,st.replyText)){cd.mark(title);ActivityLog.add(this,"replied: $title")}else ActivityLog.add(this,"no quick-reply action: $title")}catch(t:Throwable){ActivityLog.add(this,"classifier error: ${t.message}")}}
 }
 private fun sendReply(n:Notification,msg:String):Boolean{val action=n.actions?.firstOrNull{a->a.remoteInputs?.isNotEmpty()==true}?:return false;val inputs=action.remoteInputs?:return false;val i=Intent();val b=Bundle();inputs.forEach{b.putCharSequence(it.resultKey,msg)};RemoteInput.addResultsToIntent(inputs,i,b);return try{action.actionIntent.send(this,0,i);true}catch(_:Throwable){false}}
}

package expo.modules.placementguard
import android.content.Context
import java.text.SimpleDateFormat
import java.util.*
object ActivityLog{
 fun add(c:Context,m:String){val p=c.getSharedPreferences("pg_logs",Context.MODE_PRIVATE);val old=p.getString("lines","")!!.lines().filter{it.isNotBlank()};val t=SimpleDateFormat("dd MMM HH:mm:ss",Locale.getDefault()).format(Date());p.edit().putString("lines",(listOf("$t  $m")+old).take(50).joinToString("\n")).apply()}
 fun read(c:Context)=c.getSharedPreferences("pg_logs",Context.MODE_PRIVATE).getString("lines","")!!.ifBlank{"No activity yet."}
}

package expo.modules.placementguard
import android.content.*
import android.provider.Settings
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition
class PlacementGuardModule:Module(){
 private val ctx get()=requireNotNull(appContext.reactContext)
 override fun definition()=ModuleDefinition{
  Name("PlacementGuard")
  AsyncFunction("getSettings") { val s=SettingsStore(ctx); mapOf("apiKey" to s.apiKey,"enabled" to s.enabled,"dryRun" to s.dryRun,"ignoreGroups" to s.ignoreGroups,"threshold" to s.threshold,"cooldownHours" to s.cooldownHours,"model" to s.model,"replyText" to s.replyText,"exclusionsRaw" to s.exclusionsRaw) }
  AsyncFunction("saveSettings") { v:Map<String,Any?> -> val s=SettingsStore(ctx);s.apiKey=v["apiKey"] as? String?:s.apiKey;s.enabled=v["enabled"] as? Boolean?:s.enabled;s.dryRun=v["dryRun"] as? Boolean?:s.dryRun;s.ignoreGroups=v["ignoreGroups"] as? Boolean?:s.ignoreGroups;s.threshold=(v["threshold"] as? Number)?.toFloat()?:s.threshold;s.cooldownHours=(v["cooldownHours"] as? Number)?.toInt()?:s.cooldownHours;s.model=v["model"] as? String?:s.model;s.replyText=v["replyText"] as? String?:s.replyText;s.exclusionsRaw=v["exclusionsRaw"] as? String?:s.exclusionsRaw;true }
  AsyncFunction("getLogs") { ActivityLog.read(ctx) }
  AsyncFunction("openNotificationAccess") { ctx.startActivity(Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));true }
  AsyncFunction("hasNotificationAccess") { val x=Settings.Secure.getString(ctx.contentResolver,"enabled_notification_listeners").orEmpty();x.contains(ctx.packageName) }
  AsyncFunction("testNim") { val r=NimClassifier().classify(SettingsStore(ctx).apiKey,SettingsStore(ctx).model,"Test Student",listOf("Sir Accenture OA ka link kab aayega?"));mapOf("placementRelated" to r.placementRelated,"confidence" to r.confidence,"reason" to r.reason) }
 }
}
